CREATE POLICY "public reads vehicle photo files" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'vehicle-photos');
CREATE POLICY "staff uploads vehicle photo files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'vehicle-photos' AND public.is_staff(auth.uid()));
CREATE POLICY "staff updates vehicle photo files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'vehicle-photos' AND public.is_staff(auth.uid())) WITH CHECK (bucket_id = 'vehicle-photos' AND public.is_staff(auth.uid()));
CREATE POLICY "staff deletes vehicle photo files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'vehicle-photos' AND public.is_staff(auth.uid()));